import { getIconUrl } from "./getIconUrl.js";
import { commonUiIdentifiers } from "../commonUiIdentifiers.js";

export function insertIcon(iconId, parent) {
  getIconUrl(iconId).then(insert);

  function insert(url) {
    const iconImage = document.createElement("img");
    iconImage.src = url;
    iconImage.alt = iconId.split("-").join(" ");

    parent
      .querySelector(`[data-ui='${commonUiIdentifiers.weatherIcon}']`)
      .append(iconImage);
  }
}
